<div class="admin-page-head"><h1>مدیریت منوها</h1><?= CHtml::link('+ لینک جدید',array('adminMenu/create'),array('class'=>'btn btn-primary')) ?></div>
<?php foreach(array('header'=>'منوی بالای سایت','footer'=>'منوی پایین سایت') as $location=>$title): ?><section class="panel"><h2><?= $title ?></h2><table class="data-table"><thead><tr><th>عنوان</th><th>مقصد</th><th>ترتیب</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach(Hierarchy::flatten(array_values(array_filter($rows,function($r)use($location){return $r['location']===$location;}))) as $row): ?><tr><td><?= CHtml::encode(str_repeat('— ',$row['_depth']).$row['label']) ?></td><td dir="ltr"><?= CHtml::encode($row['url']) ?></td><td><?= (int)$row['sort_order'] ?></td><td><?= $row['is_active']?'فعال':'پنهان' ?></td><td><?= CHtml::link('ویرایش',array('adminMenu/update','id'=>$row['id'])) ?></td></tr><?php endforeach; ?></tbody></table></section><?php endforeach; ?>
